// One Airtable row per available day. Guards against Groq failure or garbage.
const r = $input.first().json;
const form = $('Availability Form').first().json;
const staffRec = $('Find Staff Record').first().json;

let parsed = null;
try { parsed = JSON.parse(r.choices[0].message.content); } catch (e) { parsed = null; }

const isDate = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s);
const isTime = (s) => typeof s === 'string' && /^([01]\d|2[0-3]):[0-5]\d$/.test(s);

const slots = (parsed && Array.isArray(parsed.slots) ? parsed.slots : [])
  .filter(s => isDate(s.date) && isTime(s.from) && isTime(s.to))
  .filter(s => s.from < s.to);

const confidence = parsed ? Number(parsed.confidence) || 0 : 0;

if (slots.length === 0) {
  // Nothing usable. Store the raw text so a human can enter it manually -
  // never silently drop a submission.
  return [{ json: {
    'Staff': [staffRec.id],
    'Date': form['Week starting (Monday)'],
    'Available From': '',
    'Available To': '',
    'Source': 'Manual',
    'Raw Text': form['When are you available?'],
    'Needs Review': true,
    '_parseFailed': true,
    '_staffName': form['Your name'],
  }}];
}

return slots.map(s => ({ json: {
  'Staff': [staffRec.id],
  'Date': s.date,
  'Available From': s.from,
  'Available To': s.to,
  'Source': 'Parsed',
  'Raw Text': form['When are you available?'],
  'Needs Review': confidence < 0.7,
  '_parseFailed': false,
  '_staffName': form['Your name'],
}}));

// Remove the underscore-prefixed working fields before the Airtable write.
return $input.all().map(i => {
  const j = Object.assign({}, i.json);
  delete j._parseFailed;
  delete j._staffName;
  return { json: j };
});

const items = $('Expand Slots').all().map(i => i.json);
const first = items[0];
const failed = first._parseFailed;
return [{ json: {
  'Action': 'AVAILABILITY_SUBMITTED',
  'Actor': first._staffName,
  'Source': 'Automated',
  'Staff Affected': first['Staff'],
  'After Value': failed
    ? 'Parse failed - stored raw for manual entry'
    : items.map(i => `${i['Date']} ${i['Available From']}-${i['Available To']}`).join(', '),
  'Reason': 'Weekly availability submission via form',
}}];
